import { log } from './log.js';

const DEFAULT_PATH = fileURLToPath(new URL('../data/orders.json', import.meta.url));

/** Reads the orders file (default: data/orders.json) and returns the array of orders. */
export function loadOrders(path = DEFAULT_PATH, { debug } = {}) {
  const orders = JSON.parse(readFileSync(path, 'utf8'));
  if (debug) {
    log(`Loaded ${orders.length} orders from ${path}`);
  }
  return orders;
}

